public static int obenUndVorn(Stack s, Queue q) {
    int summe = 0;
    if (!s.isEmpty()) {
        Kiste k = (Kiste) s.top();
        summe = summe + k.getGewicht();
    }
    if (!q.isEmpty()) {
        summe = summe + ((Kiste) q.head()).getGewicht();
    }
    return summe;
}

