public static int anzahlSchwerer(Stack s, int grenze) {
    Stack hilf = new Stack();
    int anzahl = 0;
    while (!s.isEmpty()) {
        Kiste k = (Kiste) s.pop();
        if (k.getGewicht() > grenze) {
            anzahl++;
        }
        hilf.push(k);
    }
    while (!hilf.isEmpty()) {
        s.push(hilf.pop());
    }
    return anzahl;
}

public static boolean istAufsteigend(Queue q) {
    Queue hilf = new Queue();
    boolean aufsteigend = true;
    boolean erstes = true;
    int vorher = 0;
    while (!q.isEmpty()) {
        int x = (Integer) q.dequeue();
        if (!erstes && x < vorher) {
            aufsteigend = false;
        }
        erstes = false;
        vorher = x;
        hilf.enqueue(x);
    }
    while (!hilf.isEmpty()) {
        q.enqueue(hilf.dequeue());
    }
    return aufsteigend;
}

