public static void einfuegenSortiert(DynArray d, Kiste k) {
    int j = 0;
    while (j < d.getLength()
            && ((Kiste) d.getItem(j)).getGewicht() <= k.getGewicht()) {
        j++;
    }
    d.insertAt(j, k);
}

