public static Kiste entferneLeichteste(DynArray d) {
    if (d.isEmpty()) {
        return null;
    }
    int minIndex = 0;
    for (int i = 1; i < d.getLength(); i++) {
        if (((Kiste) d.getItem(i)).getGewicht()
                < ((Kiste) d.getItem(minIndex)).getGewicht()) {
            minIndex = i;
        }
    }
    Kiste leichteste = (Kiste) d.getItem(minIndex);
    d.delete(minIndex);
    return leichteste;
}

