public static boolean klammernOk(String t) {
    Stack s = new Stack();
    for (int i = 0; i < t.length(); i++) {
        char c = t.charAt(i);
        if (c == '(' || c == '[' || c == '{') {
            s.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (s.isEmpty()) {
                return false;                       // (1)
            }
            char auf = (Character) s.pop();
            if (!(auf == '(' && c == ')' || auf == '[' && c == ']'
                    || auf == '{' && c == '}')) {
                return false;                       // (2)
            }
        }
    }
    return s.isEmpty();                             // (3)
}

public static int postfix(String a) {
    Stack s = new Stack();
    for (int i = 0; i < a.length(); i++) {
        char c = a.charAt(i);
        if (c >= '0' && c <= '9') {
            s.push((int) c - (int) '0');
        } else {
            int rechts = (Integer) s.pop();
            int links = (Integer) s.pop();
            int erg = links * rechts;                  // '*'
            if (c == '+') { erg = links + rechts; }
            if (c == '-') { erg = links - rechts; }
            s.push(erg);
        }
    }
    return (Integer) s.pop();
}
